      <h4 className="text-base font-semibold text-slate-900">{meta.title}</h4>
      <p className="text-sm text-slate-600">{meta.subtitle}</p>
    </div>

    <div className="h-[380px] w-full sm:h-[420px]">
      {panel === "age-bands" && (
        <ResponsiveContainer width="100%" height="100%">
          <BarChart
            data={NATIONAL_AGE_BANDS}
            layout="vertical"
            margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
          >
            <CartesianGrid strokeDasharray="3 3" stroke={COLORS.grid} />
            <XAxis type="number" tick={{ fontSize: 11 }} unit="%" />
            <YAxis
              type="category"
              dataKey="band"
              width={56}
              tick={{ fontSize: 11 }}
            />
            <Tooltip
              formatter={(v, name) => [
                `${v}%`,
                name === "electricianPct" ? "Electricians" : "Plumbers",
              ]}
            />
            <Legend />
            <Bar
              dataKey="electricianPct"
              name="Electricians"
              fill={COLORS.electrician}
              radius={[0, 3, 3, 0]}
            />
            <Bar
              dataKey="plumberPct"
              name="Plumbers"
              fill={COLORS.plumber}
              radius={[0, 3, 3, 0]}
            />
          </BarChart>
        </ResponsiveContainer>
      )}

      {panel === "state-ladder" && (
        <ResponsiveContainer width="100%" height="100%">
          <ComposedChart
            data={ladderData}
            layout="vertical"
            margin={{ top: 8, right: 24, left: 8, bottom: 8 }}
          >
            <CartesianGrid strokeDasharray="3 3" stroke={COLORS.grid} />
            <XAxis
              type="number"
              tick={{ fontSize: 11 }}
              domain={[0, 32]}
              unit="%"
            />
            <YAxis
              type="category"
              dataKey="label"
              width={36}
              tick={{ fontSize: 11 }}
            />
            <Tooltip
              formatter={(v, name) => {
                if (name === "share55") return [`${v}%`, "Share 55+"];
                if (name === "pass") return [`${v}%`, "Exam pass"];
                return [v, String(name)];
              }}
            />
            <Legend />

  if (type === "rail-headcount-after-precision-scheduling-2026") {
    return <RailHeadcountAfterPrecisionScheduling2026Dashboard />;
  }

  if (type === "medicare-part-d-glp-1-diabetes-spending-2026") {
    return <MedicarePartDGlp1DiabetesSpending2026Dashboard />;
  }

  if (type === "contract-renewal-season-vs-spot-divergence-2026") {
    return <ContractRenewalSeasonVsSpotDivergence2026Dashboard />;
  }

  if (type === "social-housing-stock-share-in-oecd-2026") {
    return <SocialHousingStockShareInOecd2026Dashboard />;
  }

  return null;
}

