              <Area
                type="monotone"
                dataKey="electrician"
                name="Electrician"
                stroke="#0f766e"
                fill="#0f766e"
                fillOpacity={0.15}
                strokeWidth={2}
              />
              <Area
                type="monotone"
                dataKey="biology"
                name="Biology"
                stroke="#15803d"
                fill="#15803d"
                fillOpacity={0.08}
                strokeWidth={2}
              />
              <Area
                type="monotone"
                dataKey="psychology"
                name="Psychology"
                stroke="#a21caf"
                fill="#a21caf"
                fillOpacity={0.06}
                strokeWidth={1.5}
              />
              <Area
                type="monotone"
                dataKey="mechEng"
                name="Mech. eng."
                stroke="#1e3a5f"
                fill="#1e3a5f"
                fillOpacity={0.05}
                strokeWidth={1.5}
                strokeDasharray="4 3"
              />
            </AreaChart>
          </ResponsiveContainer>
        )}

        {panel === "region-edge" && (
          <ResponsiveContainer width="100%" height="100%">
            <BarChart
              data={REGION_PREMIUMS}
              margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
            >
              <CartesianGrid strokeDasharray="3 3" stroke={COLORS.grid} />
              <XAxis dataKey="region" tick={{ fontSize: 10 }} interval={0} />
              <YAxis
                tick={{ fontSize: 11 }}
                tickFormatter={(v) => fmtK(v)}
                width={52}
              />
              <Tooltip
                formatter={(v, name) => [
                  name === "tradeEdgeAt10"
                    ? fmtUsd(Number(v))
                    : `${(Number(v) * 100).toFixed(0)}% of national`,
                  name === "tradeEdgeAt10"
                    ? "Trade edge @ 10y"
                    : name === "electricianPremium"
                      ? "Elec. premium"
                      : "Bio premium",
                ]}
              />
              <Legend />
              <Bar
                dataKey="tradeEdgeAt10"
                name="Trade edge @ 10y"
                fill={COLORS.trade}
                radius={[3, 3, 0, 0]}
              />
            </BarChart>
          </ResponsiveContainer>
        )}
      </div>

      <p className="mt-3 text-[11px] leading-relaxed text-slate-500">
        {SOURCE_NOTE}
      </p>
    </div>
  );
}

